import{_ as t,a0 as o,w as d,s as c,I as a,x as n,a1 as l,A as i,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用 mlocate 查找文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 mlocate 查找文件 | LCTT (201711) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 mlocate 查找文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 mlocate 查找文件 | LCTT (201711) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201711/20171106 Finding Files with mlocate","title":"使用 mlocate 查找文件","tag":"201711","desc":""},"relativePath":"201711/20171106 Finding Files with mlocate.md","filePath":"[post].md"}'),r={name:"201711/20171106 Finding Files with mlocate.md"};function g(u,s,h,b,m,k){const e=o("Link");return d(),c("div",null,[s[24]||(s[24]=a("h1",{id:"使用-mlocate-查找文件",tabindex:"-1"},[n("使用 mlocate 查找文件 "),a("a",{class:"header-anchor",href:"#使用-mlocate-查找文件","aria-label":"Permalink to “使用 mlocate 查找文件”"},"​")],-1)),s[25]||(s[25]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/question-mark.jpg?itok=dIQlOWz7",alt:"mlocate",title:"mlocate"})],-1)),s[26]||(s[26]=a("p",null,[n("在這一系列的文章中，我們將來看下 "),a("code",null,"mlocate"),n("，來看看如何快速、輕鬆地滿足你的需求。")],-1)),a("p",null,[l(e,{href:"https://www.linux.com/licenses/category/creative-commons-zero"},{default:i(()=>[...s[0]||(s[0]=[n("Creative Commons Zero",-1)])]),_:1}),s[1]||(s[1]=n("Pixabay",-1))]),s[27]||(s[27]=p(`<p>對於一個系統管理員來説，草中尋針一樣的查找文件的事情並不少見。在一台擁擠的機器上，文件系統中可能存在數十萬個文件。當你需要確定一個特定的配置文件是最新的，但是你不記得它在哪裏時怎麼辦？</p><p>如果你使用過一些類 Unix 機器，那麼你肯定用過 <code>find</code> 命令。毫無疑問，它是非常複雜和功能強大的。以下是一個只搜索目錄中的符號鏈接，而忽略文件的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find . -lname &quot;*&quot;</span></span></code></pre></div><p>你可以用 <code>find</code> 命令做幾乎無盡的事情，這是不容否認的。<code>find</code> 命令好用的時候是很好且簡潔的，但是它也可以很複雜。這不一定是因為 <code>find</code> 命令本身的原因，而是它與 <code>xargs</code> 結合，你可以傳遞各種選項來調整你的輸出，並刪除你找到的那些文件。</p><h3 id="位置、位置-讓人沮喪" tabindex="-1">位置、位置，讓人沮喪 <a class="header-anchor" href="#位置、位置-讓人沮喪" aria-label="Permalink to “位置、位置，讓人沮喪”">​</a></h3><p>然而，通常情況下簡單是最好的選擇，特別是當一個脾氣暴躁的老闆搭着你的肩膀，閒聊着時間的重要性時。你還在模糊地猜測這個你從來沒有見過的文件的路徑，而你的老闆卻肯定它在擁擠的 /var 分區的某處。</p><p>進一步看下 <code>mlocate</code>。你也許注意過它的一個近親：<code>slocate</code>，它安全地（注意前綴字母 s 代表安全）記錄了相關的文件權限，以防止非特權用户看到特權文件。此外，還有它們所起源的一個更老的，原始 <code>locate</code> 命令。</p><p><code>mlocate</code> 與其家族的其他成員（至少包括 <code>slocate</code>）的不同之處在於，在掃描文件系統時，<code>mlocate</code> 不需要持續重新掃描所有的文件系統。相反，它將其發現的文件（注意前面的 m 代表合併）與現有的文件列表合併在一起，使其可以藉助系統緩存從而性能更高、更輕量級。</p><p>在本系列文章中，我們將更仔細地瞭解 <code>mlocate</code> （由於其流行，所以也簡稱其為 <code>locate</code>），並研究如何快速輕鬆地將其調整到你心中所想的方式。</p><h3 id="小巧和緊湊" tabindex="-1">小巧和 緊湊 <a class="header-anchor" href="#小巧和緊湊" aria-label="Permalink to “小巧和	緊湊”">​</a></h3><p>除非你經常重複使用複雜的命令，否則就會像我一樣，最終會忘記它們而需要在用的時候尋找它們。<code>locate</code> 命令的優點是可以快速查詢整個文件系統，而不用擔心你處於頂層目錄、根目錄和所在路徑，只需要簡單地使用 <code>locate</code> 命令。</p><p>以前你可能已經發現 <code>find</code> 命令非常不聽話，讓你經常抓耳撓腮。你知道，丟失了一個分號或一個沒有正確轉義的特殊的字符就會這樣。現在讓我們離開這個複雜的 <code>find</code> 命令，放鬆一下，看一下這個聰明的小命令。</p><p>你可能需要首先通過運行以下命令來檢查它是否在你的系統上：</p><p>對於 Red Hat 家族：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install mlocate</span></span></code></pre></div><p>對於 Debian 家族：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get install mlocate</span></span></code></pre></div><p>發行版之間不應該有任何區別，但版本之間幾乎肯定有細微差別。小心。</p><p>接下來，我們將介紹 <code>locate</code> 命令的一個關鍵組件，名為 <code>updatedb</code>。正如你可能猜到的那樣，這是<strong>更新</strong> <code>locate</code> 命令的<strong>資料庫</strong>的命令。這名字非常符合直覺。</p><p>這個資料庫是我之前提到的 <code>locate</code> 命令的文件列表。該列表被保存在一個相對簡單而高效的資料庫中。<code>updatedb</code> 通過 cron 任務定期運行，通常在一天中的安靜時間運行。在下面的清單 1 中，我們可以看到文件 <code>/etc/cron.daily/mlocate.cron</code> 的內部（該文件的路徑及其內容可能因發行版不同）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>nodevs=$(&lt; /proc/filesystems awk &#39;$1 == &quot;nodev&quot; { print $2 }&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>renice +19 -p $$ &gt;/dev/null 2&gt;&amp;1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ionice -c2 -n7 -p $$ &gt;/dev/null 2&gt;&amp;1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/usr/bin/updatedb -f &quot;$nodevs&quot;</span></span></code></pre></div><p><strong>清單 1：</strong> 每天如何觸發 “updatedb” 命令。</p><p>如你所見，<code>mlocate.cron</code> 腳本使用了優秀的 <code>nice</code> 命令來儘可能少地影響系統性能。我還沒有明確指出這個命令每天都在設定的時間運行（但如果我沒有記錯的話，原始的 <code>locate</code> 命令與你在午夜時的計算機減速有關）。這是因為，在一些 “cron” 版本上，延遲現在被引入到隔夜開始時間。</p><p>這可能是因為所謂的 “<ruby>河馬之驚羣<rt>Thundering Herd of Hippos</rt></ruby>”問題。想像許多計算機（或飢餓的動物）同時醒來從單一或有限的來源要求資源（或食物）。當所有的“河馬”都使用 NTP 設置它們的手錶時，這可能會發生（好吧，這個寓言扯多了，但請忍受一下）。想像一下，正好每五分鐘（就像一個 “cron 任務”），它們都要求獲得食物或其他東西。</p><p>如果你不相信我，請看下配置文件 - 清單 2 中名為 <code>anacron</code> 的 cron 版本，這是文件 <code>/etc/anacrontab</code> 的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># /etc/anacrontab: configuration file for anacron</span></span>
<span class="line"><span></span></span>
<span class="line"><span># See anacron(8) and anacrontab(5) for details.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SHELL=/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PATH=/sbin:/bin:/usr/sbin:/usr/bin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MAILTO=root</span></span>
<span class="line"><span></span></span>
<span class="line"><span># the maximal random delay added to the base delay of the jobs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RANDOM_DELAY=45</span></span>
<span class="line"><span></span></span>
<span class="line"><span># the jobs will be started during the following hours only</span></span>
<span class="line"><span></span></span>
<span class="line"><span>START_HOURS_RANGE=3-22</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#period in days   delay in minutes   job-identifier   command</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1       5       cron.daily              nice run-parts /etc/cron.daily</span></span>
<span class="line"><span></span></span>
<span class="line"><span>7       25      cron.weekly             nice run-parts /etc/cron.weekly</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@monthly 45     cron.monthly            nice run-parts /etc/cron.monthly</span></span></code></pre></div><p><strong>清單 2：</strong> 運行 “cron” 任務時延遲是怎樣被帶入的。</p><p>從清單 2 可以看到 <code>RANDOM_DELAY</code> 和 “delay in minutes” 列。如果你不熟悉 cron 這個方面，那麼你可以在這找到更多的東西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># man anacrontab</span></span></code></pre></div>`,29)),a("p",null,[s[3]||(s[3]=n("否則，如果你願意，你可以自己延遲一下。有個",-1)),l(e,{href:"http://www.moundalexis.com/archives/000076.php"},{default:i(()=>[...s[2]||(s[2]=[n("很棒的網頁",-1)])]),_:1}),s[4]||(s[4]=n("（現在已有十多年的歷史）以非常合理的方式討論了這個問題。本網站討論如何使用 ",-1)),s[5]||(s[5]=a("code",null,"sleep",-1)),s[6]||(s[6]=n(" 來引入一個隨機性，如清單 3 所示。",-1))]),s[28]||(s[28]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Grab a random value between 0-240.</span></span>
<span class="line"><span>value=$RANDOM</span></span>
<span class="line"><span>while [ $value -gt 240 ] ; do</span></span>
<span class="line"><span> value=$RANDOM</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Sleep for that time.</span></span>
<span class="line"><span>sleep $value</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Syncronize.</span></span>
<span class="line"><span>/usr/bin/rsync -aqzC --delete --delete-after masterhost::master /some/dir/</span></span></code></pre></div>`,1)),a("p",null,[s[8]||(s[8]=a("strong",null,"清單 3：",-1)),s[9]||(s[9]=n("在觸發事件之前引入隨機延遲的 shell 腳本，以避免",-1)),l(e,{href:"http://www.moundalexis.com/archives/000076.php"},{default:i(()=>[...s[7]||(s[7]=[n("河馬之驚羣",-1)])]),_:1}),s[10]||(s[10]=n("。",-1))]),s[29]||(s[29]=p(`<p>在提到這些（可能令人驚訝的）延遲時，是指 <code>/etc/crontab</code> 或 root 用户自己的 crontab 文件。如果你想改變 <code>locate</code> 命令運行的時間，特別是由於磁盤訪問速度減慢時，那麼它不是太棘手。實現它可能會有更優雅的方式，但是你也可以把文件 <code>/etc/cron.daily/mlocate.cron</code> 移到別的地方（我使用 <code>/usr/local/etc</code> 目錄），使用 root 用户添加一條記錄到 root 用户的 crontab，粘貼以下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>33 3 * * * /usr/local/etc/mlocate.cron</span></span></code></pre></div><p>使用 anacron，而不是通過 <code>/var/log/cron</code> 以及它的舊的、輪轉的版本，你可以快速地告訴它上次 cron.daily 任務被觸發的時間：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -hal /var/spool/anacron</span></span></code></pre></div><p>下一次，我們會看更多的使用 <code>locate</code>、<code>updatedb</code> 和其他工具來查找文件的方法。</p><hr>`,6)),a("p",null,[s[12]||(s[12]=n("via: ",-1)),l(e,{href:"https://www.linux.com/blog/learn/intro-to-linux/2017/11/finding-files-mlocate"},{default:i(()=>[...s[11]||(s[11]=[n("https://www.linux.com/blog/learn/intro-to-linux/2017/11/finding-files-mlocate",-1)])]),_:1})]),a("p",null,[s[16]||(s[16]=n("作者：",-1)),l(e,{href:"https://www.linux.com/users/chrisbinnie"},{default:i(()=>[...s[13]||(s[13]=[n("CHRIS BINNIE",-1)])]),_:1}),s[17]||(s[17]=n(" 譯者：",-1)),l(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[14]||(s[14]=[n("geekpi",-1)])]),_:1}),s[18]||(s[18]=n(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[15]||(s[15]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[21]||(s[21]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[19]||(s[19]=[n("LCTT",-1)])]),_:1}),s[22]||(s[22]=n(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:i(()=>[...s[20]||(s[20]=[n("Linux中國",-1)])]),_:1}),s[23]||(s[23]=n(" 榮譽推出",-1))])])}const T=t(r,[["render",g]]);export{C as __pageData,T as default};
